import { MessageSquare, X, Send, Loader2, Shield, AlertCircle } from 'lucide-react';
import { ChatMessage } from '../types';
import { sendMessageToGemini } from '../services/geminiService';
import { getContactInfo } from '../services/dataService';

const ChatWidget: React.FC = () => {
  const [isOpen, setIsOpen] = useState(false);
  const [messages, setMessages] = useState<ChatMessage[]>([
    { role: 'model', text: '¡Hola! Soy el asistente virtual de SEPRI Distrito 22. ¿En qué puedo ayudarte hoy con los protocolos de tu evento?' }
  ]);
  const [input, setInput] = useState('');
  const [isLoading, setIsLoading] = useState(false);
  const [apiKey, setApiKey] = useState<string | undefined>(undefined);
  const messagesEndRef = useRef<HTMLDivElement>(null);

  const scrollToBottom = () => {
    messagesEndRef.current?.scrollIntoView({ behavior: "smooth" });
  };

  useEffect(() => {
    const fetchConfig = async () => {
      const info = await getContactInfo();
      if (info?.geminiApiKey) {
        setApiKey(info.geminiApiKey);
      }
    };
    fetchConfig();
  }, [isOpen]); // Recargar al abrir por si se actualizó en admin

  useEffect(() => {
    if (isOpen) scrollToBottom();
  }, [messages, isOpen]);

  const handleSend = async () => {
    if (!input.trim() || !apiKey) return;

    const userMsg = input;
    setInput('');

    const newMessages: ChatMessage[] = [...messages, { role: 'user', text: userMsg }];
    setMessages(newMessages);
    setIsLoading(true);

    const responseText = await sendMessageToGemini(newMessages, userMsg, apiKey);

    setMessages(prev => [...prev, { role: 'model', text: responseText }]);
    setIsLoading(false);
  };

  const handleKeyPress = (e: React.KeyboardEvent) => {
    if (e.key === 'Enter' && !e.shiftKey) {
      e.preventDefault();
      handleSend();
    }
  };

  return (
    <div className="fixed bottom-6 right-6 z-40 flex flex-col items-end">
      {/* Chat Window */}
      {isOpen && (
        <div className="bg-white w-80 md:w-96 h-[500px] rounded-2xl shadow-2xl mb-4 flex flex-col border border-gray-200 overflow-hidden animate-fade-in-up">
          {/* Header */}
          <div className="bg-sepri-medium p-4 flex justify-between items-center">
            <div className="flex items-center space-x-2">
              <div className="bg-white p-1 rounded-full">
                <Shield size={16} className="text-sepri-medium" />
              </div>
              <div>
                <h3 className="text-white font-bold text-sm">Asistente SEPRI</h3>
                <p className="text-blue-200 text-xs">En línea</p>
              </div>
            </div>
            <button onClick={() => setIsOpen(false)} className="text-white hover:bg-white/20 rounded-full p-1 transition-colors">
              <X size={20} />
            </button>
          </div>

          {/* Messages Area */}
          <div className="flex-1 overflow-y-auto p-4 bg-gray-50 space-y-4 scrollbar-hide">
            {!apiKey && (
              <div className="bg-amber-50 border border-amber-200 p-4 rounded-xl flex gap-3 items-start animate-pulse">
                <AlertCircle className="text-amber-600 flex-shrink-0" size={18} />
                <p className="text-amber-800 text-xs font-medium">
                  El Chat de IA no está configurado. Un administrador debe ingresar la API Key en el panel de configuración.
                </p>
              </div>
            )}
            {messages.map((msg, idx) => (
              <div key={idx} className={`flex ${msg.role === 'user' ? 'justify-end' : 'justify-start'}`}>
                <div 
                  className={`max-w-[80%] p-3 rounded-2xl text-sm ${
                    msg.role === 'user' 
                      ? 'bg-sepri-medium text-white rounded-tr-none' 
                      : 'bg-white text-gray-700 border border-gray-200 rounded-tl-none shadow-sm'
                  }`}
                >
                  {msg.text}
                </div>
              </div>
            ))}
            {isLoading && (
              <div className="flex justify-start">
                <div className="bg-white border border-gray-200 p-3 rounded-2xl rounded-tl-none shadow-sm">
                  <Loader2 className="animate-spin text-sepri-medium" size={18} />
                </div>
              </div>
            )}
            <div ref={messagesEndRef} />
          </div>

          {/* Input Area */}
          <div className="p-3 bg-white border-t border-gray-200">
            <div className={`flex items-center space-x-2 rounded-full px-4 py-2 ${!apiKey ? 'bg-gray-50' : 'bg-gray-100'}`}>
              <input
                type="text"
                value={input}
                onChange={(e) => setInput(e.target.value)}
                onKeyDown={handleKeyPress}
                placeholder={apiKey ? "Escribe tu consulta..." : "Chat desactivado"}
                className="flex-1 bg-transparent outline-none text-sm text-gray-700"
                disabled={isLoading || !apiKey}
              />
              <button 
                onClick={handleSend} 
                disabled={!input.trim() || isLoading || !apiKey}
                className={`p-2 rounded-full transition-colors ${input.trim() && apiKey ? 'text-sepri-medium hover:bg-blue-100' : 'text-gray-400'}`}
              >
                <Send size={18} />
              </button>
            </div>
          </div>
        </div>
      )}

      {/* Toggle Button */}
      <button
        onClick={() => setIsOpen(!isOpen)}
        className="bg-sepri-medium hover:bg-sepri-dark text-white p-4 rounded-full shadow-xl transition-all transform hover:scale-110 flex items-center justify-center"
      >
        {isOpen ? <X size={24} /> : <MessageSquare size={24} />}
      </button>
    </div>
  );
};

