        ...prev,
        teamMembers: prev.teamMembers?.map(m => m.id === editingMemberId ? { ...m, name: newMember.name!, role: newMember.role!, imageUrl: newMember.imageUrl, updatedAt: timestamp } as TeamMember : m)
