import { GoogleGenAI } from "@google/genai";
import { SYSTEM_INSTRUCTION } from "../constants";
import { ChatMessage } from "../types";

/**
 * Sends a message to the Gemini AI model and retrieves the response.
 * Uses import.meta.env.VITE_GEMINI_API_KEY for compatibility with Vite/Netlify.
 */
export const sendMessageToGemini = async (
  history: ChatMessage[],
  _newMessage: string,
  providedApiKey?: string
): Promise<string> => {
  try {
    // Prioridad: 1. API Key de la configuración admin, 2. Variable de entorno de Vite
    const apiKey = providedApiKey || import.meta.env.VITE_GEMINI_API_KEY;

    if (!apiKey) {
      return "Error: API Key de Gemini no configurada en el sistema.";
    }

    const ai = new GoogleGenAI({ apiKey });
    const modelName = 'gemini-3-flash-preview';

    const contents = history.map((msg) => ({
      role: msg.role === 'user' ? 'user' : 'model',
      parts: [{ text: msg.text }],
    }));

    const response = await ai.models.generateContent({
      model: modelName,
      contents: contents,
      config: {
        systemInstruction: SYSTEM_INSTRUCTION,
      },
    });

    const text = response.text;

    return (
      text ||
      "Lo siento, no pude generar una respuesta en este momento."
    );
  } catch (error: any) {
    console.error("Error llamando a Gemini:", error);
    if (error?.message?.includes('API_KEY_INVALID')) {
      return "La API Key configurada no es válida. Por favor revise la configuración administrativa.";
    }
    return "Hubo un error al conectar con el asistente. Por favor intenta más tarde.";
  }
};

