              </div>

              <h1 className="text-5xl md:text-7xl lg:text-8xl font-black text-white mb-6 leading-[0.9] tracking-tighter">
                <span className="block text-white/70 font-light text-2xl md:text-4xl mb-4 italic">Seguridad y Prevención del Riesgo</span>
                <span className="text-sepri-yellow">SEPRI</span>
              </h1>

              <p className="text-lg md:text-xl text-white/60 mb-10 max-w-2xl mx-auto leading-relaxed">
                Herramienta integral para la gestión de protocolos, autorización de eventos y prevención institucional.
              </p>

              <div className="flex flex-wrap gap-6 justify-center">
                <MovingBorderButton
                  as={Link}
                  to="/noticias"
                  borderRadius="1rem"
                  className="bg-white/10 text-white hover:bg-sepri-yellow hover:text-sepri-dark px-8 py-4 font-black text-xs uppercase tracking-widest border-white/20"
                  containerClassName="h-14 w-56 shadow-lg"
                >
                  Ver Novedades
                </MovingBorderButton>
              </div>
            </div>
          </div>
        </section>

        {/* Noticias Carousel */}
        <section className="container mx-auto px-4 -mt-16 relative z-30 mb-16">
          <div 
            className="bg-white/90 rounded-3xl shadow-2xl p-6 md:p-8 border-t-4 border-sepri-yellow overflow-hidden backdrop-blur-md"
